  str_homeland_dairy_title_1085 = "Começa a construção do estúdio de cinema!",
  str_homeland_dairy_title_1086 = "Doutor Errante",
  str_homeland_dairy_title_1087 = "Música eletrônica",
  str_homeland_dairy_title_1088 = "Vigília Noturna dos Jardins das Nuvens",
  str_homeland_dairy_title_1089 = "Elenco!",
  str_homeland_dairy_title_1090 = "Levante a vara!",
  str_homeland_dairy_title_1091 = "Estudo da Espécie",
  str_homeland_dairy_title_1092 = "o melhor genero",
  str_homeland_dairy_title_1093 = "luz perfeita",
  str_homeland_dairy_title_1094 = "Isso é uma torre de gato?",
  str_homeland_dairy_title_1095 = "mocassim preguiçoso",
  str_homeland_dairy_title_1096 = "O sopro da água",
  str_homeland_dairy_title_1097 = "Um Anjo Prudente",
  str_homeland_dairy_title_1098 = "Passa o inverno, chega a primavera",
  str_homeland_dairy_title_1099 = "Sabedoria de Celestita",
  str_homeland_dairy_content_101 = "Hmm, este é o meu primeiro diário em Cloud Gardens.\nEu quero construir este lugar como meu novo lar, assim como Eraveil costumava ser. Eu me pergunto se eu tenho o que é preciso.\nEu serei capaz de fazer isso com todos me apoiando!",
  str_homeland_dairy_content_102 = "Cloud Gardens está começando a se sentir em casa agora! Todo mundo está cheio de energia!\nEnquanto temos força, vamos continuar construindo a nova casa de todos! Vamos, pessoal!",
  str_homeland_dairy_content_1001 = "Carleen parece gostar de pensar sozinha junto à Fonte da Esperança.\nApenas deixe-a em paz.",
  str_homeland_dairy_content_1002 = "Hiiro fez seu desejo com cuidado...\nAcontece que ela não estava orando aos deuses por nada, mas esperava em seus desejos que ela pudesse encontrar uma direção na vida.",
  str_homeland_dairy_content_1003 = "Charon parece estar recitando um poema perto da Praça Jacinto...? Ou ele está cantando?\nAh bem. Parece que ele não desistiu de seus sonhos artísticos e ele é de fato um... bem, um sonhador admirável!",
  str_homeland_dairy_content_1004 = "Eve cuidadosamente preparou muitas coisas para Dawn e Sinsa, mas não para ela mesma.\nEve ficará satisfeita desde que passe tempo com sua família e os faça felizes, para que não precise preparar nada extra para si mesma.",
  str_homeland_dairy_content_1005 = "Com base em suas próprias necessidades, Smokey apresentar uma sugestão sobre o Sistema de Pedidos Eraveil. Ela acredita que os Aurorianos podem viver uma vida mais confortável aqui com este sistema.",
  str_homeland_dairy_content_1006 = "Taki modestamente pediu dicas sobre kit flying...\nAcontece que ele queria aprender a empinar pipas simplesmente porque achava que empinar pipas era um novo negócio lucrativo.\nEle realmente merece ser o proprietário dos Odd Jobs.",
  str_homeland_dairy_content_1007 = "Vice tem estado muito, muito ocupado ultimamente,\nParece que gerenciar as receitas e despesas aqui não é nada fácil...",
  str_homeland_dairy_content_1008 = "Parece que a Sra. Blanc pode finalmente descansar um pouco...",
  str_homeland_dairy_content_1009 = "O obcecado por tecnologia Siobhan de repente pensei que a tecnologia antiga e a tecnologia Caelestite compartilham muitas semelhanças...\nEssa nova ideia pode ser atribuída ao trabalho de horas extras?",
  str_homeland_dairy_content_1010 = "Amemori quer saber quem fez o design requintado aqui... Na verdade, ela quer replicar essa técnica e usá-la em Cloud Island, para que as pessoas possam viver uma vida melhor.",
  str_homeland_dairy_content_1011 = "Yao explicou seu plano de aposentadoria em detalhes e usou sua riqueza colossal para dissipar as preocupações de algumas pessoas comuns...",
  str_homeland_dairy_content_1012 = "Tourdog ainda não desistiu da ideia de me encomendar um texto.\nMas no final, de alguma forma, consegui virar a mesa e pedir um rascunho dele.\nUh, eu sinto que posso esperar por isso.",
  str_homeland_dairy_content_1013 = "Por alguma razão, sempre que falo com Azure, sempre terei dificuldade em responder.\nHoje, ela disse que meu lugar é como um salão de beleza. Devo tomar isso como um elogio?",
  str_homeland_dairy_content_1014 = "Hoje, Lenore finalmente entendi a diferença entre pedidos e sugestões.\nNo futuro, espero que ela possa aprender a apreciar a beleza deste mundo...",
  str_homeland_dairy_content_1015 = "Senhora Victoria vinculou a circulação da água com a vida dos aurorianos e chegou a algo profundo...",
  str_homeland_dairy_content_1016 = "Faust expressou sua preocupação para mim de uma maneira estranha ...\nO que a Mala Branca gosta de comer? Estou curioso.",
  str_homeland_dairy_content_1017 = "Giles disse que seu apetite criativo é infinitamente estimulado aqui, e ele também cantou uma nova canção de ninar.\nNo entanto, o que exatamente essa nova rima significa...?",
  str_homeland_dairy_content_1018 = "Reinhardt elogiou a infra-estrutura não muito ruim aqui, e ela propôs algumas novas teorias...\nEnfim, vamos tentar entender o ponto de vista dela primeiro?",
  str_homeland_dairy_content_1019 = [[
Gronru me convidou para jogar o "Quiz Game" com ela...
Com certeza, perdi de novo!]],
  str_homeland_dairy_content_1020 = "Uriel acredita que a dor é eterna, então esses prazeres fugazes não têm sentido...\nMas sem prazer, como alguém pode resistir ao imenso poder da dor?",
  str_homeland_dairy_content_1021 = "Vivian é um bom chefe de gabinete mesmo...\nEla acha os balanços aqui muito interessantes, então ela gostaria de construir alguns balanços por toda a Illumina.",
  str_homeland_dairy_content_1022 = "Jane está lutando com alguma coisa.\nPara a Testemunha Grimy Alley, a objetividade é uma obrigação.\nMas quando suas boas intenções quebram a objetividade, o que os outros pensariam?",
  str_homeland_dairy_content_1023 = "Acontece o que Maggie que mais odeia não é ser identificado como outra criatura, mas a atitude dos outros em relação a ela.",
  str_homeland_dairy_content_1024 = "Há um motor térmico dentro do Tumbler Puppet, e as operações de todo o Cloud Gardens dependem Brock constantemente boxe nele?!\nComo esperado, eles brincaram com ele novamente...",
  str_homeland_dairy_content_1025 = [[
Tweety parece gostar dos Jardins das Nuvens.
Mas quanto ela pode esconder em seu rabo?]],
  str_homeland_dairy_content_1026 = "Pittman sempre volta para montar os cavalos de balanço quando ninguém está por perto.\nNão entendo por que, mas ainda prometi ajudá-lo a manter esse segredo.",
  str_homeland_dairy_content_1027 = "Barton queria usar o Cloud Gardens como uma espécie de base estratégica...\nPara isso, tivemos algumas conversas profundas.",
  str_homeland_dairy_content_1028 = "Aconteceu que Sharona estava praticando as habilidades secretas do dragão que ela leu em um romance...\nAchei que ela ficaria chocada com esse romance sem sentido, mas fiquei surpreso com a resposta dela.",
  str_homeland_dairy_content_1029 = [[
Eicy comprou todas as mercadorias da loja.
Eu me pergunto quando posso gastar como ela...]],
  str_homeland_dairy_content_1030 = "Connolly está passando por algum treinamento de dessensibilização com Viceo incentivo...\nPara se acostumar com a luz, Connolly tentei tocar uma música no Hyacinth Square, e funcionou surpreendentemente bem.",
  str_homeland_dairy_content_1031 = "Sinsa acredita que há falta de lugar para lutas e corridas nos Cloud Gardens, e ele está preocupado que Eve não vai aguentar o ambiente do apartamento das meninas...\nEmbora pareça um problema, de outra perspectiva, Sinsa é realmente um bom líder e bom irmão com grande atenção aos detalhes.",
  str_homeland_dairy_content_1032 = "Fleur acha que consertar a mecânica auroriana em diferentes áreas pode trazer mais diversão nova... Depois de conversar com ele, descobri que o prazer dele é mais do que isso...",
  str_homeland_dairy_content_1033 = "eu perguntei Gram para obter dicas detalhadas sobre como melhorar minhas habilidades culinárias.\nEle me disse que não existe talento para cozinhar. A prática é a única maneira de melhorar. Ao cozinhar, é preciso evitar distrações e cozinhar com carinho para melhorar o sabor.",
  str_homeland_dairy_content_1034 = "Sua Majestade a Rainha admirava muito a Torre Jacinto em Eraveil, e tive a sorte de receber sua orientação novamente.",
  str_homeland_dairy_content_1035 = "Parece que Barton não é apenas um maníaco de guerra, mas também um maníaco de batalha... Ele está até se esforçando para observar os movimentos de spar de outras pessoas.\nMas... espere, por que as pessoas estão brigando aqui?!",
  str_homeland_dairy_content_1036 = "Kleken gabou-se de ter aprendido uma nova habilidade... Como esperado, ele me fez uma pegadinha de novo!\nNo entanto, por causa da história por trás da Técnica do Olhar, não posso ficar bravo com ele...",
  str_homeland_dairy_content_1037 = "Pierre disse que eles estavam se divertindo muito vivendo na ilha, e eu também fiquei feliz porque eles pareciam ter provocado menos e feito menos travessuras...\nMas essa felicidade terminou abruptamente quando descobri o que Clucky fez.",
  str_homeland_dairy_content_1038 = "Segui a penugem prateada no chão e percorri todo o caminho até o palheiro. E Philyshy, que havia deixado a penugem, estava roncando baixinho.\nPara evitar que outras pessoas fossem alérgicas a penugem, tive que ajudar Philyshy noivo...",
  str_homeland_dairy_content_1039 = "Hydrad me disse que ele se machucou outro dia no Mercado Negro de Umbraton, quando estava tentando brigar por um item com alguém.\nQuando eu descobri o que Hydrad queria fazer, percebi que ele também tem um lado tão diferente dele...",
  str_homeland_dairy_content_1040 = "Genevieve ficou satisfeito com a configuração. Não só o lugar oferecia seu gin favorito, mas as flores eram do seu agrado...\nNo entanto, sua reação foi um tanto interessante quando ela soube que era tudo porque Smokey estava fazendo as coisas pelas costas dela.",
  str_homeland_dairy_content_1041 = "Regina está trabalhando em seu novo single, e ela me encoraja a dar mais sugestões...\nMas de suas palavras, obtive algumas informações adicionais: em comparação com Barbara, Regina parece pensar menos em seus colegas que fingem ser outra coisa.",
  str_homeland_dairy_content_1042 = "eu não esperava Pact gostar tanto de balançar.\nVamos construir mais no futuro?",
  str_homeland_dairy_content_1043 = "Hoje, finalmente, convenci Areia para dar um passeio lá fora.\nEspero que seu sorriso possa ficar com ela para sempre.",
  str_homeland_dairy_content_1044 = "Kafka me disse que Franz está muito feliz aqui. Há muito espaço, e ele também conheceu muitos novos companheiros... e ele nem baba tanto!\nBem, espere... para onde foi a baba reduzida?",
  str_homeland_dairy_content_1045 = "Nails erroneamente acreditava que todos estavam se confessando em frente à Fonte da Esperança, então ele também começou a confessar sem parar...\nEspero que ele possa realmente encontrar consolo disso.",
  str_homeland_dairy_content_1046 = [[
Uriah parece gostar muito da vista de Eraveil.
Aproveitei a oportunidade para contar a ela meu desejo de longa data e, felizmente, ela ficou feliz em me ajudar com isso.]],
  str_homeland_dairy_content_1047 = "Viva o dia... TessaO estilo de vida de 's é um pouco invejável.\nMas nem todo mundo pode ser tão fácil e gratuito.",
  str_homeland_dairy_content_1048 = "Hachi quer transformar o Cloud Gardens em uma sala de exposições naturais.\nAlegadamente, isso pode atrair muitos turistas e trazer muitos benefícios.\nDevo confiar nele? Parece uma armadilha!",
  str_homeland_dairy_content_1049 = "Vice parece um pouco deprimido, talvez por causa desse incidente.\nFelizmente minhas piadas ruins a fizeram rir.\nVice me ajudou tanto, devo acompanhá-la para recuperar seu passado.",
  str_homeland_dairy_content_1058 = "Nina sabe andar a cavalo desde criança, então ela nunca montou um cavalo de balanço.\nQuando ela ouve que algumas pessoas não podem comprar um cavalo de balanço, ela decide fazer alguns para dar a quem quiser.\nBem... Nina é uma pessoa de coração mole.",
  str_homeland_dairy_content_1059 = "Sanae decide chamar o jardim de Canteiro de Flores do Amor.\nEla também promete cuidar disso.\nNo entanto, tudo que eu quero é que ela pare de tropeçar o tempo todo... Dói só de vê-la!",
  str_homeland_dairy_content_1060 = "Dawn está pensando calmamente na mesa...\nFico surpreso quando ela me diz que pode identificar as pessoas apenas ouvindo seus passos.\nUrgh, mas há uma exceção para tudo... Pelo menos a razão que ela dá para identificar Sinsa é frustrante.",
  str_homeland_dairy_content_1061 = "Barbara parece estar praticando seu novo single no Zaki Music Stage, mas ela parece ter algumas preocupações...\nDepois de conversar com ela, embora a atitude de Barbara em relação à música nova me choque, sua atitude em relação a outras coisas está dentro das minhas expectativas...",
  str_homeland_dairy_content_1062 = "Leona está praticando boxe enfaticamente, como se estivesse cheia de ressentimento...\nAcontece que é assim que ela desabafa.\nNo entanto, acho que disse algo que não deveria...",
  str_homeland_dairy_content_1063 = "Naroxel está conversando com pássaros em sua mesa...\nEla está preocupada com meu humor recente, então ela me ensinou uma nova técnica de respiração.",
  str_homeland_dairy_content_1064 = "Migard realmente faz jus à sua reputação como oficial especializada em biotecnologia. Um olhar é tudo o que ela precisa para saber quais árvores foram geneticamente modificadas!",
  str_homeland_dairy_content_1065 = "Como esperado de Nina... ela nunca deixa passar nenhuma inspiração!\nEu provavelmente deveria aprender com sua tenacidade quando se trata de perseguir seus sonhos.",
  str_homeland_dairy_content_1066 = "Encontrei Sahn, o líder do clã Pangalo, hoje. Ele é muito reservado. Embora houvesse alguns altos e baixos em nossas interações, todos ficaram felizes no final.",
  str_homeland_dairy_content_1067 = "Me pegou de surpresa que os Pangalos realmente gostaram do death metal de Regina! Chegaram a formar um grupo de apoio para ela! É tudo muito estranho, mas pelo menos funcionou bem.",
  str_homeland_dairy_content_1068 = "Carleen olhou para a palma da mão. De repente, ela cerrou a palma da mão como se tivesse se decidido sobre algo ou tomado uma resolução... Acontece que agora ela entende “o significado da oração”.",
  str_homeland_dairy_content_1069 = "Beryl ficou à beira do rio todo esse tempo? Poderia ser...\nPercebi que estava errado e até deixei Beryl brincar um pouco.\nNada disso importa, no entanto. É o melhor desde que Beryl pode se sentir relaxado aqui.",
  str_homeland_dairy_content_1070 = "Ciel foi incomodado por um erro de cálculo em um projeto recentemente. Ela até pensou em trabalhar para mim para ganhar algum dinheiro para comprar uma calculadora mecânica cara.\nNo final, ela percebeu que seu entendimento estava errado, não o projeto.\nParece que a inspiração às vezes faz parte de um projeto.",
  str_homeland_dairy_content_1071 = "Fia usa sua felicidade na manga.\nSob sua influência, também passei muito tempo brincando no slide.",
  str_homeland_dairy_content_1072 = "Eu dormi na espreguiçadeira a tarde toda.\nLembro-me vagamente que foi Jeno quem me colocou para dormir... Não posso continuar sonhando agora, posso?",
  str_homeland_dairy_content_1073 = "Há muitas maneiras de proteger as coisas que você ama.\nIsto é o que eu aprendi com Rainbow hoje.",
  str_homeland_dairy_content_1076 = "Mesmo em Cloud Gardens, Pollux ainda mantém suas rotinas e hábitos de Euphoria.",
  str_homeland_dairy_content_1077 = "Paloma sempre usa linguagem afiada e farpada para encobrir o quanto ela sente falta de sua família. Espero que ela possa visitar Cloud Gardens com frequência no futuro e encontrar paz interior.",
  str_homeland_dairy_content_1078 = "Casta pode não ter chegado ao cassino, mas pegou muitos peixes no rio...\nSua pesca a encantava muito mais do que o jogo.\nAcho que esse é o charme da pesca!",
  str_homeland_dairy_content_1079 = "Hedy adora sorvete também, então finalmente encontramos um terreno comum!\nMas o sorvete com sabor de \"livro antigo\" realmente existe?",
  str_homeland_dairy_content_1080 = "O juiz Jr. adora estátuas de estilo caelestita.\nEu fiz um para ele usando argila, mas ele não parecia muito satisfeito e apenas continuou vagando pela Donzela Viajante.",
  str_homeland_dairy_content_1081 = "Como esperado de Lilica! Ela realmente descobriu o que você deveria fazer com a Boneca Windelion.\nLilica também me prometeu que faria um filme sobre Eraveil, mas espero que ela escreva o roteiro corretamente...",
  str_homeland_dairy_content_1082 = "Graças a Minos, descobri como funciona a escultura Windelion Candle!",
  str_homeland_dairy_content_1083 = "Quem teria imaginado que Sadie tinha tanto talento musical? Todo mundo que ouve a melodia do tambor não pode deixar de balançar junto com ela.\nDa próxima vez vou cantar hip hop para todos!",
  str_homeland_dairy_content_1084 = "Se Michenny cuida de animaizinhos e os observa crescer, ela pode entender...\nque a importância da vida é algo que não pode ser medido em termos de valor.",
  str_homeland_dairy_content_1085 = "Hoje, decidi construir um estúdio de cinema em Cloud Gardens para todos.",
  str_homeland_dairy_content_1086 = "Beretta é muito autodisciplinada e insiste em correr todos os dias. Só hoje descobri que ela está tentando melhorar sua forma física e se tornar uma médica melhor. Ela realmente é digna da minha admiração.",
  str_homeland_dairy_content_1087 = "Axelia tem aparecido muito perto daquele Windelion Drum recentemente...\nDepois de conversar com ela, agora entendo porque ela gosta de música eletrônica.",
  str_homeland_dairy_content_1088 = "Nadine se ofereceu para ser a Nightwatch de Cloud Gardens. Não posso simplesmente ignorar sua contribuição, embora ela tenha se oferecido para esse dever!\nDevo pensar em uma recompensa para Nadine...",
